interface Product {
  id: number;
  name: string;
  price: number;
  category: string;
  inStock: boolean;
}

interface ApiRequest {
  method: string;
  body: string;
  headers: Record<string, string>;
}

interface ApiResponse {
  products?: Product[];
  product?: Product;
  error?: string;
  total?: number;
}

const catalog: Product[] = [
  { id: 1, name: 'Laptop Pro', price: 1299.99, category: 'electronics', inStock: true },
  { id: 2, name: 'Wireless Mouse', price: 29.99, category: 'electronics', inStock: true },
  { id: 3, name: 'Standing Desk', price: 499.00, category: 'furniture', inStock: false },
  { id: 4, name: 'Noise-Cancelling Headphones', price: 349.99, category: 'electronics', inStock: true },
  { id: 5, name: 'Ergonomic Chair', price: 899.00, category: 'furniture', inStock: true }
];

function main(req: ApiRequest): ApiResponse {
  const body = jsonParse(req.body, {} as any);
  const action: string = body.action || 'list';

  switch (action) {
    case 'list': {
      let filtered = catalog;
      if (body.category) filtered = filtered.filter((p: Product) => p.category === body.category);
      if (body.in_stock !== undefined) filtered = filtered.filter((p: Product) => p.inStock === body.in_stock);
      if (body.max_price) filtered = filtered.filter((p: Product) => p.price <= body.max_price);
      const sorted = body.sort === 'price_asc' ? filtered.sort((a, b) => a.price - b.price)
        : body.sort === 'price_desc' ? filtered.sort((a, b) => b.price - a.price)
        : filtered;
      return { products: sorted, total: sorted.length };
    }
    case 'get': {
      const product = catalog.find((p: Product) => p.id === body.id);
      if (!product) return { error: 'product not found' };
      return { product };
    }
    default:
      return { error: `unknown action: ${action}` };
  }
}
